	public struct BeadId : IEquatable<BeadId>, IComparable<BeadId>
	{
		public const int HundredMillion = 100000000;

		public int FileNumber => RawNumber / 100000000;

		public int BeadNumber => RawNumber % 100000000;

		public int RawNumber { get; }

		public BeadId(int beadNumber, int fileNumber)
		{
			if (fileNumber < 1)
			{
				throw new ArgumentException("FileNumber cannot be less than 0", "fileNumber");
			}
			RawNumber = fileNumber * 100000000 + beadNumber % 100000000;
		}

		public override bool Equals(object obj)
		{
			BeadId? beadId = obj as BeadId?;
			return RawNumber == beadId?.RawNumber;
		}

		public bool Equals(BeadId other)
		{
			return RawNumber == other.RawNumber;
		}

		public override int GetHashCode()
		{
			return RawNumber.GetHashCode();
		}

		public override string ToString()
		{
			return $"Bead in File {FileNumber} with number {BeadNumber}";
		}

		public int CompareTo(BeadId other)
		{
			return RawNumber.CompareTo(other.RawNumber);
		}

		public static bool operator ==(BeadId lhs, BeadId rhs)
		{
			return lhs.Equals(rhs);
		}

		public static bool operator !=(BeadId lhs, BeadId rhs)
		{
			return !(lhs == rhs);
		}

		public static bool operator >(BeadId lhs, BeadId rhs)
		{
			return lhs.BeadNumber > rhs.BeadNumber;
		}

		public static bool operator <(BeadId lhs, BeadId rhs)
		{
			return lhs.BeadNumber < rhs.BeadNumber;
		}

		public static bool operator >=(BeadId lhs, BeadId rhs)
		{
			return lhs.BeadNumber >= rhs.BeadNumber;
		}

		public static bool operator <=(BeadId lhs, BeadId rhs)
		{
			return lhs.BeadNumber <= rhs.BeadNumber;
		}
	}
