	public static class Helper
	{
		public static IEnumerable<string> SplitIntoWords(string str, int wordSize)
		{
			return from i in Enumerable.Range(0, (str.Length + wordSize - 1) / wordSize)
				select str.Substring(i * wordSize, Math.Min(str.Length - i * wordSize, wordSize));
		}

		public static string AprSysDirectoryPath(string mmVersion)
		{
			string result = null;
			List<string> list = new List<string> { "Software\\AspenTech\\AprSystem", "Software\\WOW6432Node\\AspenTech\\AprSystem" };
			foreach (RegistryHive item in new List<RegistryHive> { RegistryHive.LocalMachine })
			{
				foreach (string item2 in list)
				{
					string name = item2 + "\\" + mmVersion + "\\aplus";
					using RegistryKey registryKey = RegistryKey.OpenBaseKey(item, RegistryView.Registry64).OpenSubKey(name, writable: false);
					string text = registryKey?.GetValue("asptop")?.ToString();
					if (Directory.Exists(text))
					{
						result = Path.Combine(text, "xeq");
						break;
					}
				}
			}
			return result;
		}

		public static string IFortDirectoryPath()
		{
			string name = "SOFTWARE\\AspenTech\\Aspen Properties\\41.0";
			RegistryKey registryKey = Registry.LocalMachine.OpenSubKey(name);
			if (registryKey != null)
			{
				string text = (string)registryKey.GetValue("INTEL_DEV_REDIST");
				if (!string.IsNullOrEmpty(text))
				{
					string text2 = Path.Combine(text, "intel64");
					if (Directory.Exists(text2))
					{
						return text2;
					}
					text2 = Path.Combine(text, "bin");
					if (Directory.Exists(text2))
					{
						return text2;
					}
				}
			}
			string text3 = Path.Combine(Environment.GetEnvironmentVariable("INTEL_DEV_REDIST") ?? "", "intel64");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFilesX86), "Intel\\Shared Libraries\\intel64");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetEnvironmentVariable("IFORT_COMPILER23") ?? "", "bin\\intel64");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetEnvironmentVariable("IFORT_COMPILER21") ?? "", "bin\\intel64");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetEnvironmentVariable("INTEL_DEV_REDIST") ?? "", "redist\\intel64\\compiler");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFilesX86), "Intel\\Shared Libraries\\redist\\intel64\\compiler");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetEnvironmentVariable("INTEL_DEV_REDIST") ?? "", "bin");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFilesX86), "Intel\\Shared Libraries\\bin");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetEnvironmentVariable("IFORT_COMPILER23") ?? "", "bin");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetEnvironmentVariable("IFORT_COMPILER21") ?? "", "bin");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetEnvironmentVariable("INTEL_DEV_REDIST") ?? "", "redist\\bin\\compiler");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			text3 = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFilesX86), "Intel\\Shared Libraries\\redist\\bin\\compiler");
			if (Directory.Exists(text3))
			{
				return text3;
			}
			return null;
		}

		public static string GetFolderPath(string folder)
		{
			string result = null;
			string[] array = Environment.GetEnvironmentVariable("Path").Split(';');
			if (array.Length != 0)
			{
				for (int i = 0; i < array.Length; i++)
				{
					if (array[i].ToUpperInvariant().Contains(folder))
					{
						result = array[i];
						break;
					}
				}
			}
			return result;
		}

		public static string OomfDirectoryPath(string mmVersion)
		{
			string result = null;
			List<string> list = new List<string> { "Software\\AspenTech\\OOMF", "Software\\WOW6432Node\\AspenTech\\OOMF" };
			List<RegistryHive> obj = new List<RegistryHive>
			{
				RegistryHive.CurrentUser,
				RegistryHive.LocalMachine
			};
			string text = "";
			foreach (RegistryHive item in obj)
			{
				foreach (string item2 in list)
				{
					string name = item2 + "\\" + mmVersion;
					using RegistryKey registryKey = RegistryKey.OpenBaseKey(item, RegistryView.Registry64).OpenSubKey(name, writable: false);
					text = registryKey?.GetValue("OOMFTOP")?.ToString();
					if (Directory.Exists(text))
					{
						result = Path.Combine(text, "xeq");
						break;
					}
				}
			}
			return result;
		}

		public static IntPtr GetPtrForValueAtIndex(IntPtr dblPlexLocation, int index)
		{
			return IntPtr.Add(dblPlexLocation, index * 8);
		}

		public static double GetDoublePlexValueAtIndex(IntPtr dblPlexLocation, int index)
		{
			byte[] array = new byte[8];
			Marshal.Copy(IntPtr.Add(dblPlexLocation, index * 8), array, 0, 8);
			return BitConverter.ToDouble(array, 0);
		}

		public static void SetDoublePlexValueAtIndex(IntPtr dblPlexLocation, int index, double dblValue)
		{
			byte[] bytes = BitConverter.GetBytes(dblValue);
			IntPtr destination = IntPtr.Add(dblPlexLocation, index * 8);
			Marshal.Copy(bytes, 0, destination, bytes.Length);
		}

		public static int GetIntPlexValueAtIndex(IntPtr intPlexLocation, int index)
		{
			return (int)Marshal.ReadInt64(intPlexLocation, index * 8);
		}

		public static void SetIntPlexValueAtIndex(IntPtr intPlexLocation, int index, int iValue)
		{
			Marshal.WriteInt64(intPlexLocation, index * 8, iValue);
		}
	}
