		public static double Offset(PhysicalQuantities physicalQuantity, int column)
		{
			if (physicalQuantity == PhysicalQuantities.Temperature)
			{
				switch (column)
				{
				case 1:
					return 255.372222222222;
				case 3:
					return 273.15;
				}
			}
			return 0.0;
		}
	}
	public static class HollerithUtility
	{
		private static readonly ASCIIEncoding Encoding = new ASCIIEncoding();

		public static string ToString(RawInteger integer)
		{
			return ToString((int)(long)integer);
		}

		public static string ToString(params object[] list)
		{
			string text = string.Empty;
			for (int i = 0; i < list.Length; i++)
			{
				text += ToString((int)list[i]);
			}
			return text;
		}

		public static string ToString(int integer)
		{
			if (integer < 538976288 || integer > 2139062143)
			{
				return "";
			}
			char c = (char)(integer & 0xFF);
			char c2 = (char)((uint)(integer & 0xFF00) / 256u);
			char c3 = (char)((uint)(integer & 0xFF0000) / 65536u);
			char c4 = (char)((uint)(integer & -16777216) / 16777216u);
			return $"{c}{c2}{c3}{c4}";
		}

		public static string ToString(long integer)
		{
			return ToString((int)integer);
		}

		public static string ToString(IEnumerable<RawInteger> ints)
		{
			return string.Join("", ints.Select(ToString));
		}

		public static string ToString(IEnumerable<int> ints)
		{
			return string.Join("", ints.Select(ToString));
		}

		public static List<RawInteger> ToIntegers(string str, char pad, int? numWords = null)
		{
			int num = numWords ?? ((str.Length + 3) / 4);
			byte[] array = new byte[num * 8];
			for (int i = 0; i < num; i++)
			{
				int num2 = i * 4;
				int num3 = Math.Min(4, Math.Abs(str.Length - num2));
				int num4 = i * 8;
				if (num2 < str.Length)
				{
					Encoding.GetBytes(str, num2, num3, array, num4);
				}
				else
				{
					num3 = 0;
				}
				num4 += num3;
				int num5 = (i + 1) * 8;
				for (int j = num4; j < num5; j++)
				{
					array[j] = (byte)pad;
				}
			}
			List<RawInteger> list = new List<RawInteger>(num);
			for (int k = 0; k < array.Length; k += 8)
			{
				list.Add(BitConverter.ToInt64(array, k));
			}
			return list;
		}
	}
