		public static string FindSymbolName(int selectedDataType1, string selectedDataType2)
		{
			int selectedDataType3 = Convert.ToInt32(selectedDataType2);
			ISymbol symbol = FindSymbol(selectedDataType1, selectedDataType3);
			if (symbol == null)
			{
				return "NotFound";
			}
			return symbol.InputSymbolName;
		}

		public static string FindSymbolName(int selectedDataType1, int selectedDataType2)
		{
			ISymbol symbol = FindSymbol(selectedDataType1, selectedDataType2);
			if (symbol == null)
			{
				return "NotFound";
			}
			return symbol.InputSymbolName;
		}

		public static ISymbol FindSymbol(int selectedDataType1, string selectedDataType2)
		{
			int selectedDataType3 = Convert.ToInt32(selectedDataType2);
			return FindSymbol(selectedDataType1, selectedDataType3);
		}

		public static ISymbol FindSymbol(string selectedName, int selectedDataType1, string selectedDataType2)
		{
			int selectedDataType3 = Convert.ToInt32(selectedDataType2);
			return FindSymbol(selectedName, selectedDataType1, selectedDataType3);
		}

		public static ISymbol FindSymbol(int selectedDataType1, int selectedDataType2)
		{
			List<ISymbol> symbolList = SymbolList;
			selectedDataType2 %= 100;
			return (from symbol in symbolList
				where symbol.APDataType1 == selectedDataType1
				where symbol.APDataType2 == selectedDataType2
				select symbol).FirstOrDefault();
		}

		public static ISymbol FindSymbol(string selectedName, int selectedDataType1, int selectedDataType2)
		{
			List<ISymbol> symbolList = SymbolList;
			selectedDataType2 %= 100;
			return (from symbol in symbolList
				where symbol.InputSymbolName == selectedName
				where symbol.APDataType1 == selectedDataType1
				where symbol.APDataType2 == selectedDataType2
				select symbol).FirstOrDefault();
		}

		public static ISymbol FindSymbol(string selectedName)
		{
			return SymbolList.Where((ISymbol symbol) => symbol.InputSymbolName == selectedName).FirstOrDefault();
		}

		public static string ConvertKeywordToInteger(string selectedName, string symbolKeyword)
		{
			if (symbolKeyword == string.Empty)
			{
				return symbolKeyword;
			}
			foreach (Symbol item in SymbolList.Where((ISymbol symbol2) => symbol2.InputSymbolName == selectedName))
			{
				if (item.Table.ContainsKey(symbolKeyword))
				{
					return item.Table[symbolKeyword].ToString();
				}
			}
			return symbolKeyword;
		}

		public static string ConvertAspenDataTypesToInteger(int apDataType1, int apDataType2, string symbolKeyword)
		{
			if (symbolKeyword == string.Empty)
			{
				return symbolKeyword;
			}
			ISymbol symbol = FindSymbol(apDataType1, apDataType2);
			if (symbol == null)
			{
				return symbolKeyword;
			}
			if (symbol.Table.ContainsKey(symbolKeyword))
			{
				return symbol.Table[symbolKeyword].ToString();
			}
			return symbolKeyword;
		}

