	public static class WordUtility
	{
		public static RawInteger FirstWord(string name)
		{
			return GetWord(name, 0);
		}

		public static RawInteger SecondWord(string name)
		{
			return GetWord(name, 1);
		}

		public static RawInteger ThirdWord(string name)
		{
			return GetWord(name, 2);
		}

		public static RawInteger GetWord(string name, int index, char pad = ' ')
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(name);
			while (stringBuilder.Length < 12)
			{
				stringBuilder.Append(" ");
			}
			return HollerithUtility.ToIntegers(stringBuilder.ToString(), pad)[index];
		}
	}
